using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Inventory;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/warehouse-operations")]public sealed class WarehouseOperationsController(DadoRetailDbContext db):ControllerBase{
[HttpPost("transfer"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Transfer(TransferRequest r,CancellationToken ct){if(r.Quantity<=0||r.FromWarehouseId==r.ToWarehouseId)return BadRequest();await using var tx=await db.Database.BeginTransactionAsync(ct);var source=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==r.FromWarehouseId&&x.ProductId==r.ProductId,ct);if(source is null||source.Quantity<r.Quantity)return Conflict(new{message="Недостаточный остаток"});var dest=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==r.ToWarehouseId&&x.ProductId==r.ProductId,ct);if(dest is null){dest=new StockBalance(r.ToWarehouseId,r.ProductId);db.StockBalances.Add(dest);}var doc=Guid.NewGuid();source.Apply(-r.Quantity);dest.Apply(r.Quantity);db.StockMovements.AddRange(new StockMovement(r.FromWarehouseId,r.ProductId,-r.Quantity,StockMovementType.TransferOut,doc),new StockMovement(r.ToWarehouseId,r.ProductId,r.Quantity,StockMovementType.TransferIn,doc));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{id=doc});}
[HttpPost("write-off"),HasPermission(Permissions.InventoryApprove)]public async Task<IActionResult>WriteOff(WriteOffRequest r,CancellationToken ct){if(r.Quantity<=0||string.IsNullOrWhiteSpace(r.Reason))return BadRequest();await using var tx=await db.Database.BeginTransactionAsync(ct);var b=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==r.WarehouseId&&x.ProductId==r.ProductId,ct);if(b is null||b.Quantity<r.Quantity)return Conflict(new{message="Недостаточный остаток"});var doc=Guid.NewGuid();b.Apply(-r.Quantity);db.StockMovements.Add(new StockMovement(r.WarehouseId,r.ProductId,-r.Quantity,StockMovementType.WriteOff,doc));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{id=doc,reason=r.Reason});}}
public sealed record TransferRequest(Guid FromWarehouseId,Guid ToWarehouseId,Guid ProductId,decimal Quantity);public sealed record WriteOffRequest(Guid WarehouseId,Guid ProductId,decimal Quantity,string Reason);
